'use strict';
const icons={discover:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',insights:'<path d="M3 17l5-6 5 3 8-10"/><path d="M16 4h5v5"/><path d="M3 21h18"/>',saved:'<path d="M12 20S3 14.7 3 8.5a4.5 4.5 0 019-1.2 4.5 4.5 0 019 1.2C21 14.7 12 20 12 20Z"/>',compare:'<rect x="3" y="6" width="7" height="14" rx="2"/><rect x="14" y="3" width="7" height="17" rx="2"/>',adviser:'<path d="M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="M8 12l3 3 5-6"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.insights}</svg>`}
const labels={discover:'Explorar',insights:'Panorama',saved:'Guardados',compare:'Comparar',adviser:'Asesor'};
for(const b of document.querySelectorAll('.tabs button')){const badge=b.dataset.tab==='compare'?'<span id="compareCount" class="badge">'+state.compare.length+'</span>':'';b.innerHTML=icon(b.dataset.tab)+`<span class="navlabel">${labels[b.dataset.tab]}</span>`+badge;}
let metric='sqm';
function comparable(){return all().filter(l=>Number.isFinite(l.price)&&l.price>0&&Number.isFinite(l.area)&&l.area>0&&!l.price_from&&!l.area_from&&!l.includes_building)}
const shortMoney=n=>n>=1e6?'$'+(n/1e6).toLocaleString('es-CO',{maximumFractionDigits:1})+' M':n>=1000?'$'+(n/1000).toLocaleString('es-CO',{maximumFractionDigits:1})+' mil':money(n);
const median=arr=>{const a=[...arr].sort((x,y)=>x-y);return a.length?a.length%2?a[(a.length-1)/2]:(a[a.length/2-1]+a[a.length/2])/2:null};
function niceMax(v){if(!v)return 1;const p=10**Math.floor(Math.log10(v)),r=v/p;return(r<=1?1:r<=2?2:r<=4?4:r<=5?5:r<=8?8:10)*p}
function renderInsights(){const ls=comparable(),allRows=all(),med=median(ls.map(l=>l.price/l.area));$('#sampleSize').textContent=`${ls.length} comparables · ${allRows.length} en catálogo`;
$('#marketPulse').innerHTML=`<div class="pulse-icon">${icon('insights')}</div><div><strong>${ls.length?`${shortMoney(med)} / m² en la mediana de tu muestra`:'Tu próximo territorio empieza aquí.'}</strong><p>${ls.length?`${ls.length} anuncios comparables en ${esc(state.city)}. Una referencia del catálogo, sin avalúo.`:'Añade anuncios para descubrir relaciones entre precio y superficie.'}</p></div><button data-tab="insights">Explorar panorama ↗</button>`;
$('#insightMetrics').innerHTML=[['Mediana del precio por m²',med==null?'—':shortMoney(med),`n = ${ls.length} anuncios comparables`],['Menor precio de la muestra',ls.length?shortMoney(Math.min(...ls.map(l=>l.price))):'—','Precio anunciado, sin gastos de cierre'],['Mayor superficie',ls.length?num(Math.max(...ls.map(l=>l.area)))+' m²':'—','Solo áreas comparables de anuncios individuales']].map(([label,value,sub])=>`<div class="metricbox"><small>${label}</small><strong>${value}</strong><span>${sub}</span></div>`).join('');
$('#evidenceText').textContent=`${allRows.length} registros de ${state.city}; ${allRows.length-ls.length} ${allRows.length-ls.length===1?'registro excluido':'registros excluidos'} de los gráficos por datos incompletos, valores “desde” o mejoras incluidas. No se infiere valorización, tendencia del mercado ni edificabilidad. La disponibilidad sigue pendiente de confirmación.`;
$('#scatterNote').textContent=`n = ${ls.length}. Cada punto es un anuncio individual con precio y área conocidos. Se excluyen los proyectos con mínimos independientes y los lotes con mejoras incluidas.`;
renderScatter(ls);renderRanking(ls);
for(const b of document.querySelectorAll('[data-quick]'))b.classList.toggle('selected',b.dataset.quick==='all'&&!+$('#budget').value&&!+$('#area').value||b.dataset.quick==='affordable'&&$('#budget').value==='400000000'&&!+$('#area').value||b.dataset.quick==='large'&&$('#area').value==='5000'&&!+$('#budget').value);
for(const b of document.querySelectorAll('.tabs [data-tab]')){b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')}
}
function renderScatter(ls){if(!ls.length){$('#scatterChart').innerHTML='<div class="empty">Añade anuncios con precio y área para construir este gráfico.</div>';return}
const W=Math.max(300,Math.min(520,$('#scatterChart').clientWidth||520)),H=300,L=W<400?52:64,R=W<400?12:22,T=26,B=52,xmax=niceMax(Math.max(...ls.map(l=>l.area))*1.08),ymax=niceMax(Math.max(...ls.map(l=>l.price))*1.08),x=v=>L+v/xmax*(W-L-R),y=v=>H-B-v/ymax*(H-T-B);
let grid='';for(let i=0;i<=4;i++){const xp=x(xmax*i/4),yp=y(ymax*i/4);grid+=`<line class="chart-grid" x1="${L}" y1="${yp}" x2="${W-R}" y2="${yp}"/><text class="chart-axis" x="${L-12}" y="${yp+3}" text-anchor="end">${i?shortMoney(ymax*i/4):'$0'}</text><text class="chart-axis" x="${xp}" y="${H-B+22}" text-anchor="middle">${num(xmax*i/4)}</text>`}
$('#scatterChart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Precio anunciado frente al área de ${ls.length} anuncios comparables. Ejes lineales desde cero."><title>Precio y superficie de la muestra</title>${grid}<text class="chart-axis-title" x="${L}" y="12">Precio anunciado · COP</text><text class="chart-axis-title" x="${(L+W-R)/2}" y="${H-4}" text-anchor="middle">Área anunciada · m²</text>${ls.map((l,i)=>`<g class="chartpoint" role="button" tabindex="0" data-point="${esc(l.id)}" aria-label="${esc(l.title)}, ${money(l.price)}, ${num(l.area)} metros cuadrados. Abrir ficha."><title>${esc(l.title)} · ${money(l.price)} · ${num(l.area)} m²</title><circle class="halo" cx="${x(l.area)}" cy="${y(l.price)}" r="15"/><circle class="core" cx="${x(l.area)}" cy="${y(l.price)}" r="6"/><text x="${x(l.area)+(x(l.area)>W-100?-11:11)}" y="${y(l.price)-12}" text-anchor="${x(l.area)>W-100?'end':'start'}">${ls.length>5?'#'+(i+1):esc(l.sector||'Lote '+(i+1))}</text></g>`).join('')}</svg>`;
}
function renderRanking(ls){const value=l=>metric==='sqm'?l.price/l.area:metric==='area'?l.area:l.price,fmt=v=>metric==='area'?num(Math.round(v))+' m²':money(Math.round(v)),sorted=[...ls].sort((a,b)=>value(a)-value(b)),max=sorted.length?Math.max(...sorted.map(value)):1;
$('#rankingChart').innerHTML=sorted.length?sorted.map(l=>`<button class="barrow" data-detail="${esc(l.id)}" aria-label="Abrir ${esc(l.title)}, ${fmt(value(l))}"><span class="barlabels"><span>${esc(l.sector||l.title)}${ls.filter(x=>x.sector===l.sector).length>1?' · '+num(l.area)+' m²':''}</span><strong>${fmt(value(l))}</strong></span><span class="bartrack"><i class="barfill" style="width:${value(l)/max*100}%"></i></span><small>${num(l.area)} m² · ${money(l.price)}</small></button>`).join('')+`<div class="barbaseline"><span>0</span><span>${fmt(max)}</span></div>`:'<div class="empty">Aún no hay anuncios comparables.</div>';
}
function renderFinance({principal,r,n,quota,down,cost,annual}){let el=$('#financeChart');if(!el){el=document.createElement('div');el.id='financeChart';el.className='financechart';$('#calcResult').after(el)}const totalInterest=Math.max(0,quota*n-principal),W=Math.max(300,Math.min(650,el.clientWidth||650)),H=230,L=W<400?50:60,R=18,T=20,B=42,x=v=>L+v/n*(W-L-R),ymax=niceMax(Math.max(principal,1)),y=v=>H-B-v/ymax*(H-T-B),points=[];let balance=principal;
points.push([0,balance]);for(let month=1;month<=n;month++){balance=Math.max(0,balance*(1+r)-quota);if(month%12===0||month===n)points.push([month,balance])}let grid='';for(let i=0;i<=4;i++){const yp=y(ymax*i/4);grid+=`<line class="chart-grid" x1="${L}" y1="${yp}" x2="${W-R}" y2="${yp}"/><text class="chart-axis" x="${L-10}" y="${yp+3}" text-anchor="end">${i?shortMoney(ymax*i/4):'$0'}</text>`}for(let i=0;i<=4;i++){const month=n*i/4;grid+=`<text class="chart-axis" x="${x(month)}" y="${H-B+22}" text-anchor="middle">${(month/12).toLocaleString('es-CO',{maximumFractionDigits:1})}</text>`}const path=points.map((p,i)=>(i?'L':'M')+x(p[0]).toFixed(2)+','+y(p[1]).toFixed(2)).join(' ');const total=principal+totalInterest,capitalPct=total?principal/total*100:0;
el.innerHTML=`<div class="charthead"><div><span class="eyebrow">PROYECCIÓN DE TU ESCENARIO</span><h3>Así disminuye el saldo.</h3></div><span class="pill">Cuota fija</span></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Proyección matemática del saldo: desde ${money(principal)} hasta cero en ${n/12} años. Sin seguros ni comisiones."><defs><linearGradient id="balanceGradient" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#2c91a1" stop-opacity=".22"/><stop offset="1" stop-color="#2c91a1" stop-opacity=".01"/></linearGradient></defs>${grid}<path d="${path} L${x(n)},${y(0)} L${x(0)},${y(0)} Z" fill="url(#balanceGradient)"/><path d="${path}" fill="none" stroke="#278d9b" stroke-width="2.5" stroke-linejoin="round"/>${points.map(p=>`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="3" fill="#278d9b"><title>Año ${p[0]/12}: ${money(p[1])} de saldo</title></circle>`).join('')}<text class="chart-axis-title" x="${(W+L)/2}" y="${H-2}" text-anchor="middle">Plazo · años</text></svg><div class="financelegend"><span><i style="background:#278d9b"></i>Capital: ${money(principal)}</span><span><i style="background:#a5b9cc"></i>Intereses: ${money(totalInterest)}</span></div><div class="bartrack" style="display:flex;height:8px;margin-top:14px" role="img" aria-label="Distribución de pagos del crédito: capital ${capitalPct.toFixed(1)} por ciento, intereses ${(100-capitalPct).toFixed(1)} por ciento"><i style="width:${capitalPct}%;background:#278d9b"></i><i style="width:${total?100-capitalPct:0}%;background:#a5b9cc"></i></div><p class="chartnote">Proyección calculada con tus valores. No representa una oferta bancaria ni una predicción. No incluye seguros, comisiones ni financiación de los gastos de cierre.</p>`;
}
const originalDetails=details;
details=function(id){originalDetails(id);const l=[...catalog.listings,...state.custom].find(x=>x.id===id);if(!l)return;const history=(l.history||[]).filter(h=>Number.isFinite(h.price)&&h.price>0),block=document.createElement('div');block.className='detailchart';const heading=[...$('#modalBody').querySelectorAll('h3')].find(h=>h.textContent==='Historial documentado');if(history.length<2){block.innerHTML=`<h3>Una primera referencia.</h3><p>Solo hay ${history.length} observación de precio. El gráfico de evolución aparecerá cuando existan más registros; todavía no hay una tendencia documentada.</p><div style="display:flex;align-items:center;gap:12px;margin-top:18px"><span style="width:10px;height:10px;background:#278d9b;border-radius:50%"></span><strong>${l.price_from?'Desde ':''}${money(l.price)}</strong><span class="small">${esc(l.observed_at?.slice(0,10)||'Sin fecha')}</span></div>`}else{const W=500,H=140,pad=20,min=Math.min(...history.map(h=>h.price))*.95,max=Math.max(...history.map(h=>h.price))*1.05,start=new Date(history[0].at).getTime(),end=new Date(history.at(-1).at).getTime(),coords=history.map(h=>[pad+(new Date(h.at).getTime()-start)/Math.max(1,end-start)*(W-2*pad),H-pad-(h.price-min)/Math.max(1,max-min)*(H-2*pad)]);block.innerHTML=`<h3>Precio publicado, en el tiempo.</h3><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Historial de precios de ${esc(l.title)}"><path d="${coords.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ')}" fill="none" stroke="#278d9b" stroke-width="2"/>${coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#278d9b"><title>${esc(history[i].at)} · ${money(history[i].price)}</title></circle>`).join('')}</svg><p>${esc(history[0].at.slice(0,10))} → ${esc(history.at(-1).at.slice(0,10))} · ${history.length} observaciones. Precios anunciados, sin avalúo.</p>`}if(heading)heading.before(block);};
function sourceStatus(){const run=catalog.runs?.filter(r=>normalize(r.city)===normalize(state.city)&&normalize(r.department)===normalize(state.department)).at(-1);showModal('TRANSPARENCIA DEL RADAR',`<h2>Cada dato tiene una fuente.</h2><p class="muted">${run?'Última consulta: '+esc(new Date(run.finished_at).toLocaleString('es-CO',{timeZone:'America/Bogota'})):'Captura inicial; sin corridas automáticas registradas para este municipio.'}</p>${(run?.details||[]).map(s=>`<div class="statusrow"><i class="${s.status==='ok'?'ok':''}"></i><div><strong>${esc(s.source)}</strong><small>${s.status==='ok'?(s.method==='public_web_retrieval'?'Publicación recuperada del web o su índice; disponibilidad por confirmar.':'Consulta completada'):esc(s.reason||'No se pudo actualizar')}</small></div></div>`).join('')}<p>Los intentos fallidos conservan el dato anterior y su fecha. Un error de consulta no indica que el lote se vendió.</p><p class="small">El rastreo programado depende de GitHub Actions. Esta vista no inicia un rastreo remoto.</p>`)}
$('#showSourceStatus').onclick=sourceStatus;
for(const b of document.querySelectorAll('[data-metric]'))b.onclick=()=>{metric=b.dataset.metric;for(const x of document.querySelectorAll('[data-metric]')){x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b?'true':'false')}renderRanking(comparable())};
for(const b of document.querySelectorAll('[data-quick]'))b.onclick=()=>{$('#budget').value=b.dataset.quick==='affordable'?'400000000':'0';$('#area').value=b.dataset.quick==='large'?'5000':'0';$('#query').value='';render()};
$('#resetFilters').onclick=()=>{$('#budget').value='0';$('#area').value='0';$('#query').value='';$('#sort').value='recent';render()};
$('#listView').onclick=()=>{$('#cards').classList.add('list');$('#listView').setAttribute('aria-pressed','true');$('#gridView').setAttribute('aria-pressed','false')};$('#gridView').onclick=()=>{$('#cards').classList.remove('list');$('#gridView').setAttribute('aria-pressed','true');$('#listView').setAttribute('aria-pressed','false')};
document.addEventListener('click',e=>{const point=e.target.closest('[data-point]');if(point)details(point.dataset.point)});document.addEventListener('keydown',e=>{const point=e.target.closest('[data-point]');if(point&&['Enter',' '].includes(e.key)){e.preventDefault();details(point.dataset.point)}});
$('#appearance').onclick=()=>{state.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;$('#appearance').setAttribute('aria-label',state.theme==='dark'?'Activar modo claro':'Activar modo oscuro');persist()};document.documentElement.dataset.theme=state.theme||'light';$('#appearance').setAttribute('aria-label',state.theme==='dark'?'Activar modo claro':'Activar modo oscuro');
$('#modal').addEventListener('close',()=>render());
renderInsights();renderAdvice();

window.addEventListener('resize',()=>{clearTimeout(window.terrenoResize);window.terrenoResize=setTimeout(()=>{renderInsights();calculate()},150)});
for(const [i,el] of [...document.querySelectorAll('.summary>div')].entries()){el.setAttribute('role','button');el.tabIndex=0;const action=()=>i===0?navigate('insights'):i===1?navigate('saved'):sourceStatus();el.addEventListener('click',action);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action()}})}
